import{_ as a,o as e,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"UC — Assign Task To Creator","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/spec.md","filePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/spec.md"}'),o={name:"feature/content-task-workflow/3-6-2-assign-task-to-creator/spec.md"};function r(c,t,h,s,l,d){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="uc-—-assign-task-to-creator" tabindex="-1">UC — Assign Task To Creator <a class="header-anchor" href="#uc-—-assign-task-to-creator" aria-label="Permalink to &quot;UC — Assign Task To Creator&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./../task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.2</td></tr><tr><td>Feature</td><td>Assign Task To Creator</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>MANAGER (giao việc), CREATOR assignee (Bắt đầu làm)</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>BA confirmed Q13; đợt 2026-10-15 đã code assign/start/API/UI, chờ nghiệm thu Atlas và review tích hợp</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Gắn Task cho người làm (Creator) và tùy chọn người chịu trách nhiệm QC.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Manager, tôi muốn giao Task cho 1 Creator cụ thể, và tùy chọn thêm người QC nếu cần kiểm tra chất lượng trước khi tôi duyệt.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li><p>Chọn <code>assigneeId</code> là User ID của Creator có membership active, role CREATOR trong đúng Workspace; không nhầm với WorkspaceMember ID. Tên MEMBER trong bản cũ là thuật ngữ lịch sử.</p></li><li><p><strong>Tùy chọn</strong> chọn <code>qcAssigneeId</code> (1 Creator khác) — quyết định có/không có bước QC trong Approval Sequence (FR 3.6.9) cho Task này.</p></li><li><p>Set <code>requiresClientApproval</code> (boolean) — quyết định Task có cần Client duyệt ở cuối chuỗi hay không.</p></li><li><p>Sau Assign, Task chuyển <code>ASSIGNED</code>, Creator nhận notification.</p></li><li><p>Giao lần đầu chỉ sau DETAIL_IDENTIFIED. Manager được giao lại Creator/QC và sửa cấu hình trước khi Creator bắt đầu; Task giữ ASSIGNED. Sau khi bắt đầu/đang duyệt/terminal thì khóa thao tác này trong đợt hiện tại; reject về ASSIGNED không mở khóa lại.</p></li><li><p>QC cũng phải là Creator active của đúng Workspace và khác assignee. Quyền Manager dựa trên vai trò hiện tại của Workspace; Owner được gán Manager áp dụng quyền Manager.</p></li><li><p>Creator bấm <strong>Bắt đầu làm</strong> để chuyển ASSIGNED → IN_PROGRESS; mở trang/editor không phải bắt đầu. Lưu lần bắt đầu đầu tiên, không xóa khi reject về ASSIGNED (Q8 confirmed).</p></li><li><p>Không sửa/xóa lịch sử approval hoặc đổi ID/nguồn Task khi giao lại. Hợp đồng dấu mốc bắt đầu phải được chủ E51-03 phối hợp trước tích hợp.</p></li><li><p>Q13 confirmed 2026-10-14: không phân biệt nội bộ/thường. Mọi Task trong Workspace đều cho Client active xem/bình luận; requiresClientApproval=true/false đều hợp lệ khi các guard giao việc khác đạt. Q12 cũ không còn áp dụng; không có thao tác đổi visibility hoặc tự thay cờ duyệt.</p></li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Modal/form Assign trong trang Task Detail, dropdown chọn Creator + checkbox &#39;Cần QC&#39; + checkbox &#39;Cần Client duyệt&#39;.</li><li>Nút Bắt đầu làm riêng cho Creator được giao; không gắn side effect start vào mở editor.</li><li>Checkbox Cần Khách hàng duyệt chỉ cấu hình chuỗi duyệt kết quả; không khóa theo nguồn Task thủ công/Campaign/Request.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/assign</span></span>
<span class="line"><span>{ &quot;assigneeId&quot;: &quot;User UUID&quot;, &quot;qcAssigneeId&quot;?: &quot;User UUID&quot;, &quot;requiresClientApproval&quot;: boolean, &quot;expectedRevision&quot;: number }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { ...task..., &quot;status&quot;: &quot;ASSIGNED&quot; } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li><code>assigneeId</code> không phải Creator active của Workspace này → 400 <code>INVALID_ASSIGNEE</code>.</li><li>Task chưa qua Identify Task Detail (còn ở backlog) → 409 <code>TASK_DETAIL_NOT_IDENTIFIED</code>.</li><li>Đã bắt đầu/đang duyệt/terminal hoặc revision cũ → 409, không tự ghi đè/giao lại. Mã lỗi cụ thể chốt trong plan.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li><code>qcAssigneeId</code> trùng <code>assigneeId</code> → 400 <code>QC_CANNOT_BE_SAME_AS_ASSIGNEE</code> (người làm không thể tự QC chính mình).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Assign thành công, đúng ràng buộc QC/Client approval tùy chọn.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Approval transitions/submit/start code do chủ E51-03 phối hợp; không tự mở lại Task terminal.</li></ul><h2 id="i18n-va-theme" tabindex="-1">i18n và theme <a class="header-anchor" href="#i18n-va-theme" aria-label="Permalink to &quot;i18n và theme&quot;">​</a></h2><p>Form/dropdowns/validation/notifications feedback dùng <code>tasks.assignment.*</code>, <code>tasks.actions.start</code>, <code>tasks.errors.*</code> vi/en song song; semantic light/dark. Có loading, không có Creator khả dụng, lỗi validation, conflict và success. Không đổi UI editor hoặc các views của thành viên khác. Xem <a href="./plan.html">plan</a>, <a href="./task.html">task</a>, <a href="./test.html">test</a>.</p><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../ba/05-content-task-workflow.html">05-content-task-workflow.md</a>, <a href="./../../../ba/12-state-machines.html">12-state-machines.md</a>, <a href="./../task-detail-assignment-comments-roadmap.html">roadmap</a>.</p><h2 id="đot-tiep-tuc-2026-10-15" tabindex="-1">Đợt tiếp tục 2026-10-15 <a class="header-anchor" href="#đot-tiep-tuc-2026-10-15" aria-label="Permalink to &quot;Đợt tiếp tục 2026-10-15&quot;">​</a></h2><p>Triển khai giao/giao lại và thao tác Bắt đầu lần đầu đã chốt Q8; không triển khai submit/reject/resubmit của E51-03. Chưa coi hợp đồng Approval đã được thành viên review. Schema chưa sẵn sàng thì đọc vẫn hoạt động, mutation trả TASK_SCHEMA_NOT_READY; worker notification không tự tạo collection. Không tự chạy migration hoặc chuẩn hóa Task legacy trên Atlas.</p>`,27)])])}const p=a(o,[["render",r]]);export{g as __pageData,p as default};
